16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @Column(name = "membership_level")
76	    private Integer membershipLevel;
77	
78	    @Column(name = "bulk_signup_warning")
79	    private Boolean bulkSignupWarning;
80	
81	    @Column(name = "possible_duplicate")
82	    private Boolean possibleDuplicate;
83	
84	    @Column(name = "possible_duplicate_of")
85	    private Integer possibleDuplicateOf;
86	
87	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
88	    private Set<Pet> pets;
89	
90	    public String getAddress() {
91	        return this.address;
92	    }
93	
94	    public void setAddress(String address) {
95	        this.address = address;
96	    }
97	
98	    public String getCity() {
99	        return this.city;
100	    }
101	
102	    public void setCity(String city) {
103	        this.city = city;
104	    }
105	
106	    public String getTelephone() {
107	        return this.telephone;
108	    }
109	
110	    public void setTelephone(String telephone) {
111	        this.telephone = telephone;
112	    }
113	
114	    public String getEmail() {
115	        return this.email;
116	    }
117	
118	    public void setEmail(String email) {
119	        this.email = email;
120	    }
121	
122	    public String getPostcode() {
123	        return this.postcode;
124	    }
125	
126	    public void setPostcode(String postcode) {
127	        this.postcode = postcode;
128	    }
129	
130	    public LocalDate getRegistrationDate() {
131	        return this.registrationDate;
132	    }
133	
134	    public void setRegistrationDate(LocalDate registrationDate) {
135	        this.registrationDate = registrationDate;
136	    }
137	
138	    public LocalDate getBirthDate() {
139	        return this.birthDate;
140	    }
141	
142	    public void setBirthDate(LocalDate birthDate) {
143	        this.birthDate = birthDate;
144	    }
145	
146	    /**
147	     * The owner's {@link AgeBand age band} as of their {@link #registrationDate}, derived on
148	     * read from the owner's {@link #birthDate}. {@code null} until both the birth date and the
149	     * registration date have been supplied.
150	     */
151	    @Transient
152	    public String getAgeBand() {
153	        if (this.birthDate == null || this.registrationDate == null) {
154	            return null;
155	        }
156	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
157	    }
158	
159	    public String getCustomerCode() {
160	        return this.customerCode;
161	    }
162	
163	    public void setCustomerCode(String customerCode) {
164	        this.customerCode = customerCode;
165	    }
166	
167	    /**
168	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where
169	     * {@code YY} is the last two digits of the {@code registrationDate} year, e.g.
170	     * {@code "NSW-1A2B3C4D-M26"}. Derived from the owner's own fields; {@code null} until
171	     * both the customer code and registration date have been assigned.
172	     */
173	    @Transient
174	    public String getMembershipNumber() {
175	        if (this.customerCode == null || this.registrationDate == null) {
176	            return null;
177	        }
178	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
179	    }
180	
181	    /**
182	     * The owner's check digit: a single {@link Luhn} check digit computed over the digits
183	     * of the owner's {@link #customerCode}. {@code null} until the customer code has been
184	     * assigned.
185	     */
186	    @Transient
187	    public Integer getCheckDigit() {
188	        if (this.customerCode == null) {
189	            return null;
190	        }
191	        return Luhn.checkDigit(this.customerCode);
192	    }
193	
194	    /**
195	     * The owner's region: the canonical region derived from the owner's {@link #postcode}
196	     * via the fixed {@link RegionPostcodeTable}, falling back to the owner's {@link #city}
197	     * via the fixed {@link CityRegionTable} when the postcode is absent or in no known
198	     * range, or {@code "UNKNOWN"} when neither yields a region. This is the {@code REGION}
199	     * segment of the owner's {@link #getCustomerCode() customer code}.
200	     */
201	    @Transient
202	    public String getRegion() {
203	        return RegionPostcodeTable.regionOf(this.postcode)
204	            .orElseGet(() -> CityRegionTable.regionOf(this.city));
205	    }
206	
207	    /**
208	     * The owner's locality, read from its region-and-hash identity: the {@code REGION}
209	     * segment (everything before the first {@code '-'}) of the owner's
210	     * {@link #getCustomerCode() customer code}. Falls back to the owner's live
211	     * {@link #getRegion() region} until a customer code has been assigned.
212	     */
213	    @Transient
214	    public String getLocality() {
215	        if (this.customerCode == null) {
216	            return getRegion();
217	        }
218	        int dash = this.customerCode.indexOf('-');
219	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
220	    }
221	
222	    /**
223	     * The owner's preferred contact channel, derived on read from the owner's own
224	     * fields: {@code "EMAIL"} when the owner has an email address, otherwise
225	     * {@code "PHONE"}.
226	     */
227	    @Transient
228	    public String getContactPreference() {
229	        return (this.email == null || this.email.isBlank()) ? "PHONE" : "EMAIL";
230	    }
231	
232	    /**
233	     * The owner's identity key: the single value used to detect duplicate owners on
234	     * create. It joins the owner's (already normalized) telephone, email and household id
235	     * with {@code '|'} — {@code <telephone>|<email>|<householdId>} — a missing email or
236	     * household id contributing an empty segment. Two owners are duplicates only when
237	     * their whole identity keys are equal.
238	     */
239	    @Transient
240	    public String getIdentityKey() {
241	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
242	    }
243	
244	    private static String orEmpty(String value) {
245	        return value == null ? "" : value;
246	    }
247	
248	    public String getHouseholdId() {
249	        return this.householdId;
250	    }
251	
252	    public void setHouseholdId(String householdId) {
253	        this.householdId = householdId;
254	    }
255	
256	    public Integer getNamesakeCount() {
257	        return this.namesakeCount;
258	    }
259	
260	    public void setNamesakeCount(Integer namesakeCount) {
261	        this.namesakeCount = namesakeCount;
262	    }
263	
264	    public Integer getHouseholdSize() {
265	        return this.householdSize;
266	    }
267	
268	    public void setHouseholdSize(Integer householdSize) {
269	        this.householdSize = householdSize;
270	    }
271	
272	    /**
273	     * The owner's membership level, a number assigned on create and never below 1.
274	     * Levels 1 to 3 are earned from the owner's own fields at creation time (see
275	     * {@code MembershipLevelAssigner}); level 4 is reserved for tenure.
276	     */
277	    public Integer getMembershipLevel() {
278	        return this.membershipLevel;
279	    }
280	
281	    public void setMembershipLevel(Integer membershipLevel) {
282	        this.membershipLevel = membershipLevel;
283	    }
284	
285	    public Boolean getBulkSignupWarning() {
286	        return this.bulkSignupWarning;
287	    }
288	
289	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
290	        this.bulkSignupWarning = bulkSignupWarning;
291	    }
292	
293	    /**
294	     * Whether this owner, when created, softly matched an already-stored owner: one that
295	     * shares its last name and postcode but carries a different telephone. Assigned on
296	     * create; when {@code true}, {@link #getPossibleDuplicateOf()} identifies the matched
297	     * owner.
298	     */
299	    public Boolean getPossibleDuplicate() {
300	        return this.possibleDuplicate;
301	    }
302	
303	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
304	        this.possibleDuplicate = possibleDuplicate;
305	    }
306	
307	    /**
308	     * The id of the already-stored owner this owner softly matched on create (same last
309	     * name and postcode, different telephone), or {@code null} when it matched none.
310	     */
311	    public Integer getPossibleDuplicateOf() {
312	        return this.possibleDuplicateOf;
313	    }
314	
315	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
316	        this.possibleDuplicateOf = possibleDuplicateOf;
317	    }
318	
319	    protected Set<Pet> getPetsInternal() {
320	        if (this.pets == null) {
321	            this.pets = new HashSet<>();
322	        }
323	        return this.pets;
324	    }
325	
326	    protected void setPetsInternal(Set<Pet> pets) {
327	        this.pets = pets;
328	    }
329	
330	    public List<Pet> getPets() {
331	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
332	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
333	        return Collections.unmodifiableList(sortedPets);
334	    }
335	
336	    public void setPets(List<Pet> pets) {
337	        this.pets = new HashSet<>(pets);
338	    }
339	
340	    public void addPet(Pet pet) {
341	        getPetsInternal().add(pet);
342	        pet.setOwner(this);
343	    }
344	
345	    /**
346	     * Return the Pet with the given name, or null if none found for this Owner.
347	     *
348	     * @param name to test
349	     * @return true if pet name is already in use
350	     */
351	    public Pet getPet(String name) {
352	        return getPet(name, false);
353	    }
354	
355	    /**
356	     * Return the Pet with the given name, or null if none found for this Owner.
357	     *
358	     * @param name to test
359	     * @return true if pet name is already in use
360	     */
361	    public Pet getPet(String name, boolean ignoreNew) {
362	        name = name.toLowerCase();
363	        for (Pet pet : getPetsInternal()) {
364	            if (!ignoreNew || !pet.isNew()) {
365	                String compName = pet.getName();
366	                compName = compName.toLowerCase();
367	                if (compName.equals(name)) {
368	                    return pet;
369	                }
370	            }
371	        }
372	        return null;
373	    }
374	
375	    public Pet getPet(Integer petId) {
376	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
377	    }
378	
379	    @Override
380	    public String toString() {
381	        return new ToStringCreator(this)
382	
383	            .append("id", this.getId())
384	            .append("new", this.isNew())
385	            .append("lastName", this.getLastName())
386	            .append("firstName", this.getFirstName())
387	            .append("address", this.address)
388	            .append("city", this.city)
389	            .append("telephone", this.telephone)
390	            .append("email", this.email)
391	            .append("registrationDate", this.registrationDate)
392	            .append("customerCode", this.customerCode)
393	            .toString();
394	    }
395	}
