17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.Comparator;
20	import java.util.List;
21	import java.util.Map;
22	import java.util.Optional;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.stereotype.Component;
26	
27	/**
28	 * Canonicalises an owner telephone number to E.164 form.
29	 * <p>
30	 * Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
31	 * kept when present; otherwise the {@link #DEFAULT_COUNTRY_CODE default country code} is
32	 * assumed and a single leading {@code '0'} is dropped from the national digits. The result
33	 * is a {@code '+'} followed by {@link #MIN_DIGITS}-{@link #MAX_DIGITS} digits, so numbers
34	 * that differ only in formatting or in the way their country code is written are stored and
35	 * compared identically.
36	 * <p>
37	 * For {@link #NATIONAL_LENGTHS known country codes} the national number (the digits after
38	 * the country code) must additionally carry the exact number of digits that country uses
39	 * (e.g. {@code '+61'} requires 9 national digits, {@code '+1'} requires 10); a number whose
40	 * national part is the wrong length for its country is rejected.
41	 */
42	@Component
43	public class TelephoneNormalizer {
44	
45	    /** Country code assumed when the number carries no explicit {@code '+'} prefix. */
46	    public static final String DEFAULT_COUNTRY_CODE = "61";
47	
48	    /** The fewest digits a valid E.164 number carries after the {@code '+'}. */
49	    public static final int MIN_DIGITS = 8;
50	
51	    /** The most digits a valid E.164 number carries after the {@code '+'}. */
52	    public static final int MAX_DIGITS = 15;
53	
54	    /**
55	     * Country code (without {@code '+'}) to the exact national-number length it requires.
56	     * Numbers whose country code is not listed here are checked only against the generic
57	     * {@link #MIN_DIGITS}-{@link #MAX_DIGITS} bounds.
58	     */
59	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
60	
61	    /** Known country codes, longest first, so the country code is matched greedily. */
62	    private static final List<String> COUNTRY_CODES = NATIONAL_LENGTHS.keySet().stream()
63	        .sorted(Comparator.comparingInt(String::length).reversed())
64	        .toList();
65	
66	    /** Separators removed before interpreting the number: spaces, dashes and brackets. */
67	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
68	
69	    /**
70	     * Converts a raw telephone into its canonical E.164 representation.
71	     *
72	     * @param raw the telephone as supplied by the client, possibly {@code null}
73	     * @return the E.164 number ({@code '+'} then {@value #MIN_DIGITS}-{@value #MAX_DIGITS}
74	     *         digits), or empty when {@code raw} cannot form a valid E.164 number
75	     */
76	    public Optional<String> toE164(String raw) {
77	        if (raw == null) {
78	            return Optional.empty();
79	        }
80	        String stripped = SEPARATORS.matcher(raw).replaceAll("");
81	        String digits = stripped.startsWith("+")
82	            ? stripped.substring(1)
83	            : DEFAULT_COUNTRY_CODE + dropLeadingZero(stripped);
84	        return isValid(digits) ? Optional.of("+" + digits) : Optional.empty();
85	    }
86	
87	    private String dropLeadingZero(String national) {
88	        return national.startsWith("0") ? national.substring(1) : national;
89	    }
90	
91	    private boolean isValid(String digits) {
92	        return digits.chars().allMatch(c -> c >= '0' && c <= '9')
93	            && digits.length() >= MIN_DIGITS && digits.length() <= MAX_DIGITS
94	            && hasValidNationalLength(digits);
95	    }
96	
97	    /**
98	     * Checks the national-number length for a known country code. Numbers whose leading
99	     * digits match no known country code pass this check, relying on the generic bounds.
100	     */
101	    private boolean hasValidNationalLength(String digits) {
102	        return COUNTRY_CODES.stream()
103	            .filter(digits::startsWith)
104	            .findFirst()
105	            .map(code -> digits.length() - code.length() == NATIONAL_LENGTHS.get(code))
106	            .orElse(true);
107	    }
108	}
