181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
184	        HttpHeaders headers = new HttpHeaders();
185	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
186	        this.registrationDateAssigner.assign(owner);
187	        if (this.cityCapacityChecker.isCityAtCapacity(owner)) {
188	            return new ResponseEntity<>(HttpStatus.CONFLICT);
189	        }
190	        if (this.dailyRegistrationLimiter.isDailyLimitReached(owner.getRegistrationDate())) {
191	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
192	        }
193	        this.householdAssigner.assign(owner);
194	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
195	        boolean householdDuplicate = this.householdDuplicateChecker.isDuplicate(owner);
196	        if (householdDuplicate && !sharesHousehold) {
197	            return new ResponseEntity<>(HttpStatus.CONFLICT);
198	        }
199	        if (this.identityDuplicateChecker.isDuplicate(owner)) {
200	            return new ResponseEntity<>(HttpStatus.CONFLICT);
201	        }
202	        boolean declaredHouseholdMember = householdDuplicate && sharesHousehold;
203	        this.householdSizeAssigner.assign(owner);
204	        this.customerCodeAssigner.assign(owner);
205	        this.namesakeCounter.assign(owner);
206	        this.membershipLevelAssigner.assign(owner);
207	        this.bulkSignupWarningAssigner.assign(owner);
208	        this.possibleDuplicateAssigner.assign(owner, declaredHouseholdMember);
209	        this.clinicService.saveOwner(owner);
210	        this.ownerCreationAuditLogger.logCreated(owner);
211	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
212	        headers.setLocation(UriComponentsBuilder.newInstance()
213	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
214	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
215	    }
